// A keyboard- and touch-friendly work gallery. Only the selected video's player is mounted.
export function initMedia(c){
 const q=s=>document.querySelector(s), esc=s=>String(s||'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
 const url=s=>{try{const u=new URL(s,location.href);return ['http:','https:'].includes(u.protocol)?u.href:null}catch{return null}};
 q('#media-intro').textContent=c.mediaIntro;
 q('#media-craft').innerHTML=c.mediaCraft.map(x=>`<article class="craft-card reveal"><div class="craft-meta"><span>${x.number}</span><small>${esc(x.subtitle)}</small></div><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p><ul>${x.terms.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></article>`).join('');
 q('#media-tools').innerHTML=c.mediaTools.map((t,i)=>`<article class="tool reveal"><b aria-hidden="true">${['Pr','Ae','Ps','Lr'][i]}</b><div><h4>${esc(t)}</h4><p>${esc(c.mediaToolDetails[i])}</p></div></article>`).join('');
 q('#media-process').innerHTML=c.mediaProcess.map((x,i)=>`<article class="process-step reveal"><span>0${i+1}</span><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p></article>`).join('');
 q('#gear-list').innerHTML=c.gear.map((g,i)=>`<li><span>0${i+1}</span><div><strong>${esc(g)}</strong><p>${esc(c.gearDetails[i])}</p></div></li>`).join('');
 const films=c.films;let current=0;
 const gallery=q('#films');gallery.className='cinema-gallery';gallery.setAttribute('role','region');gallery.setAttribute('aria-roledescription','carousel');gallery.setAttribute('aria-label','Selected media work');
 gallery.innerHTML=`<div class="cinema-stage"><div id="film-screen" class="film-screen"></div><aside class="film-story"><div class="film-meta"><span id="film-category"></span><span id="film-count"></span></div><h3 id="film-title"></h3><p id="film-caption"></p><dl><div><dt>MY ROLE</dt><dd id="film-role"></dd></div><div><dt>TOOLS</dt><dd id="film-tools"></dd></div><div><dt>FORMAT</dt><dd id="film-format"></dd></div></dl><details class="film-notes"><summary>Behind the edit</summary><p id="film-story-text"></p></details><div class="film-arrows"><button id="film-prev" aria-label="Previous work">←</button><span>EXPLORE THE CUTS</span><button id="film-next" aria-label="Next work">→</button></div></aside></div><div id="film-strip" class="film-strip" aria-label="Choose a work"></div><p id="film-announcement" class="sr-only" aria-live="polite" aria-atomic="true"></p>`;
 if(!films.length){gallery.innerHTML='<p>New work will appear here.</p>';return;}
 q('#film-strip').innerHTML=films.map((f,i)=>`<button class="film-thumb thumb-${i%3}" data-film="${i}" aria-label="Show ${esc(f.title)}"><span class="thumb-art" aria-hidden="true"><i></i><b>${String(i+1).padStart(2,'0')}</b></span><span class="thumb-label"><strong>${esc(f.title)}</strong><small>${esc(f.category)}</small></span><span class="thumb-arrow" aria-hidden="true">↗</span></button>`).join('');
 function poster(f){const p=f.poster&&url(f.poster);return p?`<img src="${esc(p)}" alt="${esc(f.title)}" loading="lazy">`:'';}
 function render(announce=false){const f=films[current],valid=f.url&&url(f.url);q('#film-category').textContent=f.category||'SELECTED WORK';q('#film-count').textContent=`${String(current+1).padStart(2,'0')} / ${String(films.length).padStart(2,'0')}`;q('#film-title').textContent=f.title;q('#film-caption').textContent=f.caption;q('#film-role').textContent=f.role;q('#film-tools').textContent=f.tools;q('#film-format').textContent=f.format||'Film';q('#film-story-text').textContent=f.story||f.caption;q('.film-notes').open=false;
 const screen=q('#film-screen');screen.className=`film-screen scene-${current%3}${f.format?.includes('9:16')?' portrait-film':''}`;
 screen.innerHTML=`<div class="film-cover">${poster(f)}<div class="film-composition" aria-hidden="true"><i></i><i></i><i></i><span>${current%3===0?'MOTION':current%3===1?'PERSPECTIVE':'MOMENT'}</span></div><div class="screen-top"><span>ZEEKAEDITS / ${String(current+1).padStart(2,'0')}</span><span>${valid?'SELECTED WORK':'DEMO PREVIEW'}</span></div>${valid?'<button class="play-film" aria-label="Play '+esc(f.title)+'"><span aria-hidden="true">▷</span><small>WATCH FILM</small></button>':'<div class="demo-film-label"><span>YOUR FILM GOES HERE</span><small>Illustrative layout · not actual portfolio work</small></div>'}<div class="screen-bottom"><span>${esc(f.category)}</span><span>${esc(f.format)}</span></div></div>`;
 if(valid)q('.play-film').addEventListener('click',()=>play(f,valid));
 gallery.querySelectorAll('[data-film]').forEach((b,i)=>{b.classList.toggle('selected',i===current);b.setAttribute('aria-pressed',String(i===current))});
 if(announce)q('#film-announcement').textContent=`Work ${current+1} of ${films.length}: ${f.title}`;
 }
 function play(f,link){const u=new URL(link);let embed='';if(u.hostname==='youtu.be')embed='https://www.youtube-nocookie.com/embed/'+encodeURIComponent(u.pathname.slice(1));if(['youtube.com','www.youtube.com'].includes(u.hostname)){const id=u.searchParams.get('v')||u.pathname.match(/^\/(?:shorts|embed)\/([^/]+)/)?.[1];if(id)embed='https://www.youtube-nocookie.com/embed/'+encodeURIComponent(id);}if(['vimeo.com','www.vimeo.com'].includes(u.hostname)&&/^\/\d+$/.test(u.pathname))embed='https://player.vimeo.com/video'+u.pathname;
 const screen=q('#film-screen');if(embed)screen.innerHTML=`<iframe src="${esc(embed)}?autoplay=1" title="${esc(f.title)}" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen></iframe>`;else if(/\.(mp4|webm)$/i.test(u.pathname)){screen.innerHTML=`<video controls autoplay playsinline src="${esc(link)}" aria-label="${esc(f.title)}"></video>`;}else{screen.innerHTML=`<div class="external-film"><p>This work is hosted on ${esc(u.hostname)}.</p><a class="button" href="${esc(link)}" target="_blank" rel="noopener">Open film ↗</a></div>`;}screen.querySelector('iframe,video,a')?.focus();}
 function move(delta){current=(current+delta+films.length)%films.length;render(true)}
 q('#film-prev').addEventListener('click',()=>move(-1));q('#film-next').addEventListener('click',()=>move(1));gallery.querySelectorAll('[data-film]').forEach(b=>b.addEventListener('click',()=>{current=Number(b.dataset.film);render(true)}));
 gallery.addEventListener('keydown',e=>{if(e.target.closest('video,iframe,details'))return;if(e.key==='ArrowRight'){e.preventDefault();move(1)}if(e.key==='ArrowLeft'){e.preventDefault();move(-1)}});
 let start; q('#film-screen').addEventListener('touchstart',e=>{if(e.target.closest('video,iframe'))return;start={x:e.touches[0].clientX,y:e.touches[0].clientY}},{passive:true});q('#film-screen').addEventListener('touchend',e=>{if(!start)return;const dx=e.changedTouches[0].clientX-start.x,dy=e.changedTouches[0].clientY-start.y;if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)*1.5)move(dx<0?1:-1);start=null},{passive:true});render();
}
